"""Layout widgets — widgets that arrange other widgets.

Inspired by Flutter's layout taxonomy: Column and Row are flex
containers, Center centers a single child within the available space,
and ListView is a scrollable list with an optional lazy ``builder``
mode that only renders the visible items.
"""

from __future__ import annotations

from typing import Any, Callable, Literal

from workpeg.ui.state import Binding
from workpeg.ui.widgets.base import BaseWidget, WidgetChild


class MultiChildLayout(BaseWidget):
    """Base for widgets that arrange **several** children (Column, Row, GridView).

    Positional args are the children (compiler API); the keyword ``children``
    list is the legacy API. Subclasses add their own layout props.
    """

    widget_type = "MultiChildLayout"

    def __init__(
        self,
        *args: WidgetChild,
        children: list[WidgetChild] | None = None,
        **kwargs: Any,
    ):
        super().__init__(**kwargs)
        self._children = list(args) if args else (children or [])

    def children(self) -> list[WidgetChild]:
        return self._children


class SingleChildLayout(BaseWidget):
    """Base for widgets that wrap **one** child (Center, Align).

    The child is the single positional argument — the same shape custom
    single-child components use for their slot.
    """

    widget_type = "SingleChildLayout"

    def __init__(self, child: WidgetChild = None, **kwargs: Any):
        super().__init__(**kwargs)
        self.child = child

    def children(self) -> list[WidgetChild]:
        return [self.child] if self.child is not None else []


class Column(MultiChildLayout):
    """A vertical flex container — lays its children top-to-bottom."""

    widget_type = "Column"


class Row(MultiChildLayout):
    """A horizontal flex container — lays its children left-to-right."""

    widget_type = "Row"


class Align(SingleChildLayout):
    """Aligns a single child within the space it occupies (Flutter's ``Align``).

    Compiler API::

        Align(Text("top right"), alignment="top_right")

    ``alignment`` is one of the nine snake_case anchors
    (``top_left`` … ``center`` … ``bottom_right``); it defaults to ``center``,
    so ``Align(child)`` behaves like ``Center(child)``. Like Center, Align
    stretches to fill the remaining space in a Column.
    """

    widget_type = "Align"

    def __init__(
        self,
        child: WidgetChild = None,
        *,
        alignment: str = "center",
        **kwargs: Any,
    ):
        super().__init__(child, **kwargs)
        self.alignment = alignment

    def props(self) -> dict[str, Any]:
        return {"alignment": self.alignment}


class Center(Align):
    """Centers a single child horizontally and vertically.

    Compiler API::

        Center(Text("Hello"))

    Flutter-faithful: ``Center`` *is* an ``Align`` with the alignment fixed to
    center. Inside a Column it stretches to fill the remaining space, so a lone
    ``Center(...)`` centers its child in the viewport.
    """

    widget_type = "Center"

    def __init__(self, child: WidgetChild = None, **kwargs: Any):
        super().__init__(child, alignment="center", **kwargs)


def resolve_edges(
    all: int | None,
    horizontal: int | None,
    vertical: int | None,
    top: int | None,
    right: int | None,
    bottom: int | None,
    left: int | None,
) -> dict[str, int]:
    """Resolve EdgeInsets-style keywords into four sides.

    Precedence (most specific wins): a per-side value, then its axis
    (``horizontal`` / ``vertical``), then ``all``, else 0.
    """
    def pick(side: int | None, axis: int | None) -> int:
        if side is not None:
            return side
        if axis is not None:
            return axis
        return all if all is not None else 0

    return {
        "top": pick(top, vertical),
        "right": pick(right, horizontal),
        "bottom": pick(bottom, vertical),
        "left": pick(left, horizontal),
    }


class Padding(SingleChildLayout):
    """Insets its child by the given padding — Flutter's ``Padding``/``EdgeInsets``.

    Pass ``all`` for every side, ``horizontal`` / ``vertical`` for an axis, or a
    per-side ``top`` / ``right`` / ``bottom`` / ``left``; more specific wins::

        Padding(Text("hi"), all=8)
        Padding(card, horizontal=16, vertical=8)
        Padding(child, all=8, top=16)        # 16 on top, 8 elsewhere
    """

    widget_type = "Padding"

    def __init__(
        self,
        child: WidgetChild = None,
        *,
        all: int | None = None,
        horizontal: int | None = None,
        vertical: int | None = None,
        top: int | None = None,
        right: int | None = None,
        bottom: int | None = None,
        left: int | None = None,
        **kwargs: Any,
    ):
        super().__init__(child, **kwargs)
        self._edges = resolve_edges(
            all, horizontal, vertical, top, right, bottom, left
        )

    def props(self) -> dict[str, Any]:
        return dict(self._edges)


class SizedBox(SingleChildLayout):
    """A box with a fixed ``width`` and/or ``height`` — Flutter's ``SizedBox``.

    The child is optional. With no child it's the canonical spacer — drop a
    fixed gap into a Row or Column::

        SizedBox(Text("boxed"), width=120, height=40)
        Row(Text("a"), SizedBox(width=24), Text("b"))   # 24px horizontal gap
        Column(Text("x"), SizedBox(height=12), Text("y"))
    """

    widget_type = "SizedBox"

    def __init__(
        self,
        child: WidgetChild = None,
        *,
        width: int | None = None,
        height: int | None = None,
        **kwargs: Any,
    ):
        super().__init__(child, **kwargs)
        self.width = width
        self.height = height

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {}
        if self.width is not None:
            p["width"] = self.width
        if self.height is not None:
            p["height"] = self.height
        return p


class Container(SingleChildLayout):
    """A composite box around a single (optional) child — Flutter's ``Container``.

    A pragmatic subset: inner ``padding`` and outer ``margin`` (uniform px),
    fixed ``width``/``height``, a background ``color``, a background image
    (``background``, a URL — ``cover``-fit, centred), rounded ``radius``, and
    child ``alignment`` (the nine anchors). For per-side insets, compose with the
    ``Padding`` widget::

        Container(Text("card"), padding=12, color="#eef", radius=8)
        Container(width=80, height=80, color="tomato")          # a coloured box
        Container(child, background="https://…/hero.jpg")       # cover image

    ``background`` is scheme-allowlisted (only ``http(s)`` / relative URLs;
    ``javascript:``/``data:`` are dropped) and the ``url(...)`` is built by the
    runtime, so it can't inject CSS — unlike a raw ``style`` value, where
    ``url(...)`` is blocked.
    """

    widget_type = "Container"

    def __init__(
        self,
        child: WidgetChild = None,
        *,
        padding: int | None = None,
        margin: int | None = None,
        width: int | None = None,
        height: int | None = None,
        color: str | None = None,
        background: str | None = None,
        radius: int | None = None,
        alignment: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(child, **kwargs)
        self.padding = padding
        self.margin = margin
        self.width = width
        self.height = height
        self.color = color
        self.background = background
        self.radius = radius
        self.alignment = alignment

    def props(self) -> dict[str, Any]:
        keys = ("padding", "margin", "width", "height", "color", "background",
                "radius", "alignment")
        return {k: getattr(self, k) for k in keys if getattr(self, k) is not None}


class FlexChild(SingleChildLayout):
    """Base for flex children — a child weighted by ``flex`` inside a Row/Column."""

    def __init__(self, child: WidgetChild = None, *, flex: int = 1, **kwargs: Any):
        super().__init__(child, **kwargs)
        self.flex = flex

    def props(self) -> dict[str, Any]:
        return {"flex": self.flex}


class Expanded(FlexChild):
    """Fills the free space along a Row/Column's main axis — Flutter's ``Expanded``.

    Several ``Expanded`` children divide the space by their ``flex`` weights::

        Row(Expanded(left), Expanded(right, flex=2))   # right gets 2/3
    """

    widget_type = "Expanded"


class Flexible(FlexChild):
    """Like ``Expanded`` but *may* take less than its share (loose fit)."""

    widget_type = "Flexible"


class Spacer(BaseWidget):
    """Flexible empty space along the main axis — Flutter's ``Spacer``.

    ``Row(a, Spacer(), b)`` pushes ``a`` and ``b`` to the two ends.
    """

    widget_type = "Spacer"

    def __init__(self, *, flex: int = 1, **kwargs: Any):
        super().__init__(**kwargs)
        self.flex = flex

    def props(self) -> dict[str, Any]:
        return {"flex": self.flex}


class Outlet(BaseWidget):
    """The slot in a :class:`~workpeg.ui.app.Shell` where the routed child
    renders — React Router's ``<Outlet/>`` / Flutter's ``ShellRoute`` body.

    Place a single ``Outlet()`` anywhere in a shell's ``build()``; the active
    route's page mounts into it. Navigating between the shell's child routes
    swaps only the Outlet, so the rest of the shell never repaints::

        class AppShell(Shell):
            def build(self):
                return Row(Sidebar(...), Outlet(), align="stretch")

    Takes no children or props.
    """

    widget_type = "Outlet"

    def props(self) -> dict[str, Any]:
        return {}


class ScaffoldSlots(BaseWidget):
    """INTERNAL — the :class:`~workpeg.ui.Scaffold`'s slot-handoff element.

    Carries exactly the host's five customization slots — ``nav``, ``fixed``,
    ``top_nav``, ``main``, ``attached``, in that order (optional ones may be
    ``None``). The runtime renders them into stable slot roots and hands the
    element to the bundled ``scaffold.js``, which draws the surrounding chrome
    (sidebar rail, business switcher, top-nav actions …) — so the shell's
    design updates out of band of app releases. Use :class:`Scaffold`, not
    this, in an app.
    """

    widget_type = "ScaffoldSlots"

    def __init__(self, nav: Any, fixed: Any, top_nav: Any, main: Any,
                 attached: Any, **kwargs: Any):
        super().__init__(**kwargs)
        self.nav = nav
        self.fixed = fixed
        self.top_nav = top_nav
        self.main = main
        self.attached = attached

    def children(self) -> list[Any]:
        return [self.nav, self.fixed, self.top_nav, self.main, self.attached]


class Authenticated(BaseWidget):
    """Gate a subtree on the signed-in session — like a route guard.

    On mount it checks the session once (a credentialed ``GET`` to
    ``/v1/users/me/``). While checking it shows a loader; on success it renders
    its single child and exposes the user via the ``user`` sentinel; on a 4xx it
    redirects to ``https://accounts.workpeg.com/login?peg=<peg>&ep=<path>`` (the
    peg is the page's namespace); a 5xx / network error shows a retry rather than
    bouncing an authenticated user. Use it directly, or wrap a
    :class:`Shell`'s chrome so the whole app is gated and the check runs once::

        class AppShell(Shell):
            def build(self):
                return Authenticated(Row(Sidebar(...), Outlet()))

    Takes exactly one child and no keywords.
    """

    widget_type = "Authenticated"

    def __init__(self, child: BaseWidget, **kwargs: Any):
        super().__init__(**kwargs)
        self.child = child

    def props(self) -> dict[str, Any]:
        return {}


class Tooltip(BaseWidget):
    """A hover tooltip around a single child — a floating bubble with the given
    ``text``.

    It augments the child (adds no box, so layout and the hover area are exactly
    the child's). Choose where it points with ``placement`` —
    ``"top"`` (default), ``"bottom"``, ``"left"`` or ``"right"`` — and theme it
    with a ``color`` (else it inherits the pegment tokens). It appears instantly
    on hover and dismisses on any click or scroll::

        Tooltip(Button("Save", on_click=self.save),
                text="Save your work (⌘S)", placement="bottom")
        Tooltip(icon, text="Danger", placement="right", color="#e23b3b")

    For a quick one-off, the universal ``title=`` prop is a shortcut (top
    placement, default theme).
    """

    widget_type = "Tooltip"

    def __init__(
        self,
        child: BaseWidget,
        *,
        text: str,
        placement: str = "top",
        color: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(**kwargs)
        self.child = child
        self.text = text
        self.placement = placement
        self.color = color

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"text": self.text, "placement": self.placement}
        if self.color is not None:
            p["color"] = self.color
        return p


class Resizable(BaseWidget):
    """Make a single child horizontally resizable by dragging a grip on its edge
    — like dragging a panel border or an Excel column.

    It augments the child (adds no box of its own): a thin grip sits on the chosen
    ``side`` (``"right"`` default, or ``"left"``), and dragging it sets the
    child's width, clamped to the optional ``min`` / ``max`` (px). The child needs
    a definite starting width (e.g. a ``Container(width=...)``); pass a ``key`` to
    persist the dragged width across re-renders::

        Resizable(Container(sidebar, width=268), min=200, max=460, key="rail")
    """

    widget_type = "Resizable"

    def __init__(
        self,
        child: BaseWidget,
        *,
        min: int | None = None,
        max: int | None = None,
        side: str = "right",
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.child = child
        self.min = min
        self.max = max
        self.side = side

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"side": self.side}
        if self.min is not None:
            p["min"] = self.min
        if self.max is not None:
            p["max"] = self.max
        return p


class Modal(BaseWidget):
    """A modal dialog over a dimmed backdrop, shown while ``open`` is truthy.

    Declarative: keep an ``open`` flag in ``State`` and flip it. The content is a
    single child; the backdrop covers the viewport (``position: fixed``, so it's
    never clipped). Clicking the backdrop or pressing ``Esc`` calls ``on_close``
    (give it a method that sets ``open`` back to ``False``); clicks inside the
    card don't dismiss. An optional ``title`` renders a header::

        class Page(App):
            show = State(False)
            def open(self): self.show = True
            def close(self): self.show = False
            def build(self):
                return Column(
                    Button("Open", on_click=self.open),
                    Modal(
                        Column(Text("Delete this item?"),
                               Button("Delete", on_click=self.confirm)),
                        open=self.show, on_close=self.close, title="Confirm",
                    ),
                )
    """

    widget_type = "Modal"

    def __init__(
        self,
        child: BaseWidget,
        *,
        open: bool | Binding,
        on_close: Any = None,
        title: str | Binding | None = None,
        width: int | None = None,
        flush: bool = False,
        **kwargs: Any,
    ):
        super().__init__(**kwargs)
        self.child = child
        self.open = open
        self.on_close = on_close
        self.title = title
        # `width` widens the card (px, capped to the viewport); `flush` drops the
        # card's inner padding and clips overflow, so the child can run media to
        # the rounded edge (a hero image, a full-bleed header).
        self.width = width
        self.flush = flush

    def children(self) -> list[WidgetChild]:
        return [self.child]

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"open": self.open}
        if self.title is not None:
            p["title"] = self.title
        if self.width is not None:
            p["width"] = self.width
        if self.flush:
            p["flush"] = True
        return p


class Drawer(BaseWidget):
    """A side panel that reveals along the edge it sits on, shown while
    ``open`` is truthy — the chat-history panel pattern.

    Declarative like :class:`Modal`: keep an ``open`` flag in ``State`` and
    flip it. Unlike a Modal it is **in flow**: place it in a ``Row`` beside
    your content (after it for a right drawer — the usual spot — or before it
    for a left one) and opening animates its width from ``0`` to ``width``,
    *pushing* the content rather than floating over it (no backdrop). The
    panel inside keeps a fixed width so its content never reflows
    mid-animation. Pressing ``Esc`` fires ``on_close``; an optional ``title``
    renders a header row with a close button (which also fires it)::

        class Page(App):
            show = State(False)
            def open(self): self.show = True
            def close(self): self.show = False
            def build(self):
                return Row(
                    Column(Button("History", on_click=self.open), ...),
                    Drawer(
                        Column(...),                    # the panel body
                        open=self.show, on_close=self.close, title="History",
                    ),
                )
    """

    widget_type = "Drawer"

    def __init__(
        self,
        child: BaseWidget,
        *,
        open: bool | Binding,
        on_close: Any = None,
        title: str | Binding | None = None,
        width: int | None = None,
        **kwargs: Any,
    ):
        super().__init__(**kwargs)
        self.child = child
        self.open = open
        self.on_close = on_close
        self.title = title
        # panel width in px (the open wrapper animates to it); default 300.
        self.width = width

    def children(self) -> list[WidgetChild]:
        return [self.child]

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"open": self.open}
        if self.title is not None:
            p["title"] = self.title
        if self.width is not None:
            p["width"] = self.width
        return p


class Menu(BaseWidget):
    """A dropdown menu — a clickable ``trigger`` that reveals a panel of
    ``items`` (a button menu, an actions list, a custom picker).

    Self-contained, no state to manage: clicking the trigger toggles the panel,
    and a click anywhere else, a click on an item, or pressing ``Esc`` closes it.
    ``placement`` is the side the panel opens toward — ``"bottom"`` (default),
    ``"top"``, ``"left"`` or ``"right"``::

        Menu(
            Button("Options ▾"),
            Link("Profile", href="/profile"),
            Link("Settings", href="/settings"),
            Button("Sign out", on_click=self.sign_out),
            placement="bottom",
        )

    The trigger is the first child; the rest are the menu items (which may be
    spread from a comprehension). Don't give the trigger its own ``on_click`` —
    the Menu wires the open/close.

    The open panel floats (``position: fixed``, anchored to the trigger), so it
    isn't clipped by a scrollable or ``overflow: hidden`` ancestor — a Menu at the
    bottom of a sidebar rail opens out over the page rather than being cut off.

    Pass ``lazy=True`` to defer building the panel's contents until the menu is
    **first opened** — so a ``FutureBuilder`` inside it only fetches on demand,
    not on page load. Handy for a picker whose data isn't worth a network call
    unless the user actually opens it (and the loading state finally shows).
    """

    widget_type = "Menu"

    def __init__(
        self,
        trigger: WidgetChild,
        *items: WidgetChild,
        placement: str = "bottom",
        lazy: bool = False,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.trigger = trigger
        self.items = items
        self.placement = placement
        self.lazy = lazy

    def children(self) -> list[WidgetChild]:
        return [self.trigger, *self.items]

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"placement": self.placement}
        if self.lazy:
            p["lazy"] = True
        return p


class Step(BaseWidget):
    """One step inside :class:`Wizard` — a ``label`` for the progress bar and
    the content shown while it is the current step. Author-time grouping only;
    valid solely as a direct child of ``Wizard(...)``.

    ``optional=True`` lets the wizard move past it without it counting as
    answered — the marker still fills in, but nothing is claimed about it.
    """

    widget_type = "Step"

    def __init__(self, label: str | Binding, child: WidgetChild, *,
                 optional: bool = False, **kwargs: Any):
        super().__init__(**kwargs)
        self.label = label
        self.child = child
        self.optional = optional

    def children(self) -> list[WidgetChild]:
        return [self.child]


class Wizard(BaseWidget):
    """A wizard — a numbered progress bar plus the current step's panel::

        Wizard(
            Step("Vehicle", Column(...)),
            Step("Driver", Column(...)),
            Step("Cover", Column(...)),
            value=self.step, on_change=self.go,
        )

    **Controlled, deliberately.** Unlike :class:`Tabs`, which tracks its own
    active tab, a Wizard always takes ``value`` and ``on_change``. A wizard
    step is normally gated on something the widget cannot see — whether the
    answers so far validate, whether a price came back — so the runtime
    moving on its own would be moving without the one fact that decides it.
    You own the index; you decide when it changes.

    **A step is not a tab.** Clicking a FINISHED step goes back to it, which
    is the point of showing them. Clicking one further ahead does nothing:
    the runtime refuses it rather than trusting the bar, because the bar is
    drawn from the same ``value`` the click would change.

    ``Next``/``Back`` are ordinary Buttons you write, so their labels,
    placement and disabled rules are yours::

        Row(Button("Back", on_click=self.back, variant="secondary-gray"),
            Button("Continue", on_click=self.next))

    That is not an omission to be tidied later: ``Form`` exposes no validity
    binding, so a built-in Continue could not know when to disable itself and
    would have to lie.
    """

    widget_type = "Wizard"

    def __init__(
        self,
        *steps: WidgetChild,
        value: int | Binding = 0,
        on_change: Callable | None = None,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.steps = steps
        self.value = value
        self.on_change = on_change

    def children(self) -> list[WidgetChild]:
        return list(self.steps)


class Tab(BaseWidget):
    """One tab inside :class:`Tabs` — a ``label`` (shown in the tab bar) and the
    content widget revealed when it's the active tab. Author-time grouping only;
    valid solely as a direct child of ``Tabs(...)``.

    A header can carry an ``icon`` and a ``badge`` beside its label, and
    ``vertical=True`` stacks them over it instead of beside it::

        Tab("Messages", Column(...), icon="message-circle", badge="12")
        Tab("Activity", Column(...), icon="activity", vertical=True)
    """

    widget_type = "Tab"

    def __init__(self, label: str | Binding, child: WidgetChild, *,
                 icon: str | None = None, badge: str | None = None,
                 vertical: bool = False, disabled: bool = False,
                 **kwargs: Any):
        super().__init__(**kwargs)
        self.label = label
        self.child = child
        self.icon = icon
        self.badge = badge
        self.vertical = vertical
        self.tab_disabled = disabled

    def children(self) -> list[WidgetChild]:
        return [self.child]


class Tabs(BaseWidget):
    """A tabbed container — a bar of ``Tab(label, content)`` headers with the
    active panel shown beside it. Self-contained, no state to manage: clicking a
    tab reveals its panel (only the active panel is visible). ``placement`` is
    where the bar sits — ``"top"`` (default), ``"bottom"``, ``"left"`` or
    ``"right"``::

        Tabs(
            Tab("Overview", Column(...)),
            Tab("Settings", Column(...)),
            Tab("Activity", ListView(...)),
        )

    For a *controlled* strip (e.g. synced to a route), pass ``value`` (the active
    tab index, bound to state) and ``on_change`` (called with the new index);
    otherwise the runtime tracks the active tab itself.

    Two looks, from the design system's ``tabs.html``. ``variant="primary"``
    (the default) is the segmented control — a track the selected tab sits
    on as a pill; ``variant="secondary"`` is the underline, a baseline the
    row sits on with the selected tab marking its segment. ``rounded=True``
    makes a primary strip fully round, and ``size="lg"`` enlarges both::

        Tabs(Tab("15m", ...), Tab("30m", ...), rounded=True)
        Tabs(Tab("All", ...), Tab("Unread", ...), variant="secondary")
    """

    widget_type = "Tabs"

    def __init__(
        self,
        *tabs: WidgetChild,
        value: int | Binding | None = None,
        on_change: Callable | None = None,
        placement: str = "top",
        variant: str = "primary",
        rounded: bool = False,
        size: str = "md",
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.tabs = tabs
        self.variant = variant
        self.rounded = rounded
        self.size = size
        self.value = value
        self.on_change = on_change
        self.placement = placement

    def children(self) -> list[WidgetChild]:
        return list(self.tabs)

    def props(self) -> dict[str, Any]:
        return {"placement": self.placement}


class AccordionItem(BaseWidget):
    """One row of an :class:`Accordion` — a title and the content it reveals.

    Author-time grouping only, and valid solely as a direct child of
    ``Accordion(...)``; the same shape ``Tab`` has inside ``Tabs``.

    The title is a **string or a widget**, and that choice is the point of
    the design. A plain label covers the common case; a widget covers the
    rest, because a real accordion header is usually an icon and some text
    and sometimes a badge::

        AccordionItem("How secure is Workpeg?", Text("Very."))
        AccordionItem(Row(Icon("shield"), Text("Security")), Text("..."))

    ``icon=`` is the shorthand for the ordinary case and puts a Tabler icon
    in the header's own icon slot — which is not the same as putting an
    ``Icon`` inside a title widget, because the slot is what the panel's
    indentation lines up against.

    ``open=`` starts the row expanded. ``disabled=`` makes this one row
    inert while leaving the rest of the accordion working.
    """

    widget_type = "AccordionItem"

    def __init__(
        self,
        title: WidgetChild,
        child: WidgetChild,
        *,
        icon: str | None = None,
        open: bool = False,
        disabled: bool | Binding = False,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, disabled=disabled, **kwargs)
        self.title = title
        self.child = child
        self.icon = icon
        self.open = open

    def children(self) -> list[WidgetChild]:
        return [self.title, self.child]

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {}
        if self.icon is not None:
            p["icon"] = self.icon
        if self.open:
            p["open"] = True
        return p


class Accordion(BaseWidget):
    """A stack of expandable rows — Flutter's ``ExpansionPanelList``.

    Self-contained, like :class:`Tabs`: clicking a row opens it and the
    runtime tracks which are open, so there is no state to wire up for the
    ordinary case::

        Accordion(
            AccordionItem("How secure is Workpeg?", Text("Very.")),
            AccordionItem("What about privacy?",    Text("Also very.")),
        )

    ``variant`` is the design-system treatment — ``"default"`` (separated
    rows) or ``"elevated"`` (one raised surface). ``separators=False``
    drops the rules between rows. ``exclusive=True`` closes the others when
    one opens, which is what most people mean by "accordion"; the default
    lets several stand open at once, which is what the design's own page
    shows.

    ``indicator`` picks the open/close affordance: ``"chevron"`` (default),
    ``"double"``, ``"circle"`` or ``"plusminus"``.

    For a *controlled* accordion — one whose open rows are driven by your
    own state — pass ``value`` (a list of open indices) and ``on_change``.
    """

    widget_type = "Accordion"

    #: The container treatments the stylesheet defines.
    VARIANTS = ("default", "elevated")

    #: The indicator styles. ``chevron`` is the default and needs no class.
    INDICATORS = ("chevron", "double", "circle", "plusminus")

    def __init__(
        self,
        *items: WidgetChild,
        variant: Literal["default", "elevated"] = "default",
        indicator: Literal[
            "chevron", "double", "circle", "plusminus"
        ] = "chevron",
        separators: bool = True,
        exclusive: bool = False,
        value: list | Binding | None = None,
        on_change: Callable | None = None,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.items = items
        self.variant = variant
        self.indicator = indicator
        self.separators = separators
        self.exclusive = exclusive
        self.value = value
        self.on_change = on_change

    def children(self) -> list[WidgetChild]:
        return list(self.items)

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"variant": self.variant}
        if self.indicator != "chevron":
            p["indicator"] = self.indicator
        if not self.separators:
            p["separators"] = False
        if self.exclusive:
            p["exclusive"] = True
        return p


#: The shipped accordions, as ``name -> the props they preset``.
#:
#: A LIBRARY OF PRESETS, not a parallel implementation. Each entry is the
#: base :class:`Accordion` with some arguments already chosen, so there is
#: one widget, one parser arm, one renderer and one stylesheet rule set
#: behind all of them — and adding another is a line in this table rather
#: than a new arm in five files. The button work found the same taxonomy
#: copied into seven places with nothing checking they agreed; this is the
#: shape that avoids repeating it.
#:
#: A preset only ever sets DEFAULTS. Every one still takes the base's whole
#: signature, so `ElevatedAccordion(..., indicator="plusminus")` works and
#: `ElevatedAccordion(..., variant="default")` un-presets itself.
ACCORDION_PRESETS: dict[str, dict[str, Any]] = {
    "ElevatedAccordion": {"variant": "elevated"},
    "PlainAccordion": {"separators": False},
    "ExclusiveAccordion": {"exclusive": True},
}


class _PresetAccordion(Accordion):
    """Base for the shipped accordions. Subclasses set ``preset`` only."""

    #: Overridden by each subclass; merged under the caller's arguments.
    preset: dict[str, Any] = {}

    def __init__(self, *items: WidgetChild, **kwargs: Any):
        merged = dict(self.preset)
        merged.update(kwargs)
        super().__init__(*items, **merged)


class ElevatedAccordion(_PresetAccordion):
    """The rows on one raised, rounded surface — ``variant="elevated"``.

        ElevatedAccordion(
            AccordionItem("Shipping", Text("Free over $50.")),
            AccordionItem("Returns",  Text("30 days.")),
        )
    """

    widget_type = "Accordion"
    preset = ACCORDION_PRESETS["ElevatedAccordion"]


class PlainAccordion(_PresetAccordion):
    """No rules between the rows — ``separators=False``."""

    widget_type = "Accordion"
    preset = ACCORDION_PRESETS["PlainAccordion"]


class ExclusiveAccordion(_PresetAccordion):
    """Opening one row closes the others — ``exclusive=True``.

    What most people mean by "an accordion"; the design's own page shows
    the other behaviour, so the base keeps that and this names the choice.
    """

    widget_type = "Accordion"
    preset = ACCORDION_PRESETS["ExclusiveAccordion"]


class Divider(BaseWidget):
    """A thin rule separating content — Flutter's ``Divider`` (horizontal) or
    ``VerticalDivider`` (``vertical=True``). ``thickness`` (px) and ``spacing``
    (px of margin around it) are coerced to numbers and written via the CSSOM, so
    they can't inject CSS. No content::

        Divider()
        Divider(spacing=12)
        Row(left, Divider(vertical=True), right)
    """

    widget_type = "Divider"

