    def props(self) -> dict[str, Any]:
        props = {
            "spacing": self.spacing,
            "run_spacing": self.run_spacing,
            "direction": self.direction,
        }
        if self.cross_alignment is not None:
            props["cross_alignment"] = self.cross_alignment
        return props


