class Offstage(SingleChildLayout):
    """Hides its child (kept mounted, so state survives) when ``offstage`` is
    true — Flutter's ``Offstage``. ``offstage`` may be a state expression, so it
    toggles reactively::

        Offstage(Text("secret"), offstage=self.hidden)
    """

    widget_type = "Offstage"

    def __init__(self, child: WidgetChild = None, *, offstage: bool = True,
                 **kwargs: Any):
        super().__init__(child, **kwargs)
        self.offstage = offstage

    def props(self) -> dict[str, Any]:
        return {"offstage": self.offstage}


class TableCell(SingleChildLayout):
    """One cell — a title line over an optional subtext line, and/or a child
    widget.

    The two-line anatomy the design documents::

        TableCell(title="Ada Lovelace", subtext="ada@example.com")

    A cell may also hold a WIDGET, which is how a control gets into a table::

        TableCell(Select(options=CODES), title="Country code")
        TableCell(Row(Button("Edit"), Button("Delete"), gap=8))

    A bare widget in a :class:`TableRow` is still a perfectly good cell —
    ``TableCell`` is the sugar for the anatomy and the alignment, not a
    requirement. Every cell gets the same inner box either way, which is what
    lets an input inside one shrink with its column instead of forcing it
    wider.

    ``align`` is ``start`` / ``center`` / ``end``; ``nowrap`` keeps a cell on
    one line, which is what you want for a date or an amount and not for a
    sentence.
    """

    widget_type = "TableCell"

    def __init__(
        self,
        child: WidgetChild = None,
        *,
        title: str | Binding | None = None,
        subtext: str | Binding | None = None,
        align: Literal["start", "center", "end"] = "start",
        nowrap: bool = False,
        **kwargs: Any,
    ):
        super().__init__(child, **kwargs)
        self.title = title
        self.subtext = subtext
        self.align = align
        self.nowrap = nowrap

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {}
        if self.title is not None:
            p["title"] = self.title
        if self.subtext is not None:
            p["subtext"] = self.subtext
        if self.align != "start":
            p["align"] = self.align
        if self.nowrap:
            p["nowrap"] = True
        return p


class TableHeader(MultiChildLayout):
    """The header row — becomes ``<thead>``.

    At most one per table, and it must be the table's first child. A separate
    widget rather than a flag on :class:`TableRow` so that rule is a fact
    about the node's TYPE, which the compiler reads directly, instead of a
    keyword it would have to audit on both the literal-row path and the
    comprehension path::

        Table(
            TableHeader(TableCell(title="Name"), TableCell(title="Score")),
            TableRow(TableCell(title="Ada"), TableCell(title="99")),
        )

    Author-time grouping only, like :class:`TableRow`: valid solely as a
    direct child of :class:`Table`.
    """

    widget_type = "TableHeader"


class TableRow(MultiChildLayout):
    """One body row — becomes a ``<tr>`` in ``<tbody>``.

    Author-time grouping only; valid solely as a direct child of
    :class:`Table`, and it takes cells and nothing else.

    **Row STATE — selected, per-row click, a disabled row — is deliberately
    not here yet**, and the reason is structural rather than an oversight.
    The compiler flattens every row's cells into one row-major list, because
    the usual way to build a table is
    ``*[TableRow(...) for row in self.rows]`` and that comprehension lowers to
    a single node the parser never unrolls. A flat list of cells has nowhere
    to hang a fact about a ROW. Giving rows their own IR is the next step and
    it moves the parser, the generator and the runtime together; until then a
    row keyword would be an API the compiler refuses, which is worse than an
    API that is not there.
    """

    widget_type = "TableRow"


class Table(MultiChildLayout):
    """A table — a header and a body, in the platform's own style::

        Table(
            TableHeader(TableCell(title="Name"), TableCell(title="Email")),
            *[TableRow(TableCell(title=c.name, subtext=c.role),
                       TableCell(title=c.email))
              for c in self.people],
        )

    Cells hold widgets as readily as text, so a control belongs in one
    without ceremony — see :class:`TableCell`.

    **Sorting, searching and paging are VIEW operations**, done in the
    browser over the rows already rendered::

        Table(..., sortable=True, search=True, page_size=25)

    ``sortable`` makes every column header a sort control. ``search`` adds a
    filter box (pass a string to set its placeholder). ``page_size`` adds a
    pager. They compose in that order: the filter narrows, the sort orders
    what is left, the pager shows a slice of it.

    They work on the RENDERED TEXT, because that is all a table has — the
    compiler flattens every row into one cell list, so there is nowhere to
    hang the underlying value. A column of numbers or dates is detected and
    compared as such; anything else compares as text. If you need to sort by
    something the table does not show, sort in Python before you build it.

    **The frame.** ``dividers`` (default on) draws the 1px rules between
    columns; the rules between rows are the design and are not optional.
    ``hover`` lights a body row under the pointer. ``density="compact"``
    tightens the padding.

    **Size.** ``height`` (px) caps the box and scrolls the body inside it.
    ``resize_x`` / ``resize_y`` let somebody drag the BOX itself — pure CSS,
    so it behaves the same in a chat reply as in an app, at the cost of the
    browser's own unstyled grabber and no effect at all on iOS Safari.

    **Columns.** ``resizable=True`` is the older, different feature: drag the
    grip on a header cell's right edge to set that COLUMN's width, clamped by
    ``min_col`` / ``max_col``, persisted across re-renders by ``key``. The two
    are not alternatives — one sizes the box, the other sizes a column.

    ``border=`` is the pre-header spelling of ``dividers`` and is honoured:
    any non-zero value means dividers on, zero means off.

    **A bar above, a bar below.** ``toolbar=`` puts a strip across the top of
    the table and ``footer=`` one across the bottom; each takes any widget, so
    a title and a search box go in the first and pagination in the second::

        Table(
            TableHeader(TableCell(title="Name"), TableCell(title="Email")),
            *rows,
            toolbar=Row(Text("Recent deployments"), TextInput(...), gap=12),
            footer=Row(Button("Previous"), Button("Next"), gap=8),
        )

    All four combinations are supported, and the FRAME moves with them: with
    either bar present the border and the rounded corners belong to the card
    that wraps all three, because two boxes each drawing an edge is a double
    line at every corner. With neither, the table's own frame is the rounded
    thing, exactly as before.

    They are keywords rather than child widgets on purpose. A table's cells
    are one flat row-major list whose row boundary is arithmetic, so a bar
    arriving as a child would shift every cell one column — and a
    ``TableFooter`` sitting next to ``TableHeader`` would read as an HTML
    ``<tfoot>``, which is a different thing entirely.
    """

    widget_type = "Table"

    def __init__(
        self,
        *rows: WidgetChild,
        toolbar: WidgetChild = None,
        footer: WidgetChild = None,
        sortable: bool = False,
        search: bool | str = False,
        page_size: int | None = None,
        dividers: bool = True,
        hover: bool = True,
        density: Literal["comfortable", "compact"] = "comfortable",
        height: int | None = None,
        resize_x: bool = False,
        resize_y: bool = False,
        resizable: bool = False,
        min_col: int | None = None,
        max_col: int | None = None,
        border: int | None = None,
        clip: bool = True,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(*rows, key=key, **kwargs)
        self.sortable = sortable
        self.search = search
        self.page_size = page_size
        # Stored, and deliberately NOT returned from `props()` — the two
        # existing widget-valued keywords do the same (`FutureBuilder.loading`,
        # `Dismissible.background`). `build()` is PARSED rather than executed,
        # so the compiler reads these off the source; `props()` feeds only the
        # legacy `to_schema` path, where a widget would have to be serialised.
        self.toolbar = toolbar
        self.footer = footer
        # `border=` folded rather than ignored: an app that says border=0 is
        # asking for no rules, and silently drawing them would be the same
        # surprise as silently dropping the keyword.
        self.dividers = dividers if border is None else bool(border)
        self.hover = hover
        # WHO SCROLLS A WIDE TABLE. `clip=True` (the default) keeps the
        # frame a scroll container: the table scrolls INSIDE its card and
        # the card stays where it is. `clip=False` lets the whole thing
        # overflow outward, so whatever scrolls around it moves the table
        # AS ONE — frame, border and all — rather than sliding content
        # behind a fixed edge.
        self.clip = clip
        self.density = density
        self.height = height
        self.resize_x = resize_x
        self.resize_y = resize_y
        self.resizable = resizable
        self.min_col = min_col
        self.max_col = max_col

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {}
        if not self.dividers:
            p["dividers"] = False
        if not self.hover:
            p["hover"] = False
        if self.density != "comfortable":
            p["density"] = self.density
        if self.height is not None:
            p["height"] = self.height
        if self.resize_x:
            p["resize_x"] = True
        if self.resize_y:
            p["resize_y"] = True
        if self.resizable:
            p["resizable"] = True
            if self.min_col is not None:
                p["min_col"] = self.min_col
            if self.max_col is not None:
                p["max_col"] = self.max_col
        return p


class ListView(MultiChildLayout):
    """A scrollable list of widgets, with an optional lazy builder mode.

    Static mode renders every child up front inside a scrollable
    container (like Flutter's ``ListView(children: [...])``)::

        ListView(
            Text("First"),
            Text("Second"),
            height=300,
        )

    Builder mode (``ListView.builder``) is lazy: items are built
    on demand and only the visible window is rendered, so lists of
    thousands of rows stay fast::

        ListView.builder(
            item_count=10_000,
            item_builder=lambda i: Text(f"Row {i}"),
            item_extent=40,
            height=400,
        )

    Props:

    - ``height`` / ``width`` — viewport size (px int or CSS string).
      Builder mode defaults to a 400px-tall viewport.
    - ``item_extent`` — fixed main-axis size of every item in px.
      Required for precise virtualization in builder mode (default 40).
    - ``gap`` — space between items in px (default 8).
    - ``padding`` — CSS padding for the viewport.
    - ``align`` — cross-axis alignment of items:
      ``start | center | end | stretch`` (default ``stretch``).
    - ``direction`` — ``vertical`` (default) or ``horizontal``.
    - ``reverse`` — lay items out from the end (item 0 nearest the
      bottom/right edge), like Flutter's ``reverse: true``.
    """

    widget_type = "ListView"

    def __init__(
        self,
        *children: WidgetChild,
        height: str | int | None = None,
        width: str | int | None = None,
        item_extent: int | None = None,
        gap: int | None = None,
        padding: str | int | None = None,
        align: Literal["start", "center", "end", "stretch"] = "stretch",
        direction: Literal["vertical", "horizontal"] = "vertical",
        reverse: bool = False,
        item_count: int | None = None,
        item_builder: Callable[[int], BaseWidget] | None = None,
        **kwargs: Any,
    ):
        # MultiChildLayout stores the static children and forwards the common
        # BaseWidget params (key/visible/disabled/metadata) in **kwargs.
        super().__init__(*children, **kwargs)
        self.height = height
        self.width = width
        self.item_extent = item_extent
        self.gap = gap
        self.padding = padding
        self.align = align
        self.direction = direction
        self.reverse = reverse
        self.item_count = item_count
        self.item_builder = item_builder

    @classmethod
    def builder(
        cls,
        *,
        item_count: int,
        item_builder: Callable[[int], BaseWidget],
        **kwargs: Any,
    ) -> "ListView":
        """Lazy constructor — items are built on demand from
        ``item_builder(index)`` and only the visible window is rendered."""
        return cls(item_count=item_count, item_builder=item_builder, **kwargs)

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {
            "gap": self.gap,
            "padding": self.padding,
            "align": self.align,
            "direction": self.direction,
            "reverse": self.reverse,
        }
        if self.height is not None:
            p["height"] = self.height
        if self.width is not None:
            p["width"] = self.width
        if self.item_extent is not None:
            p["item_extent"] = self.item_extent
        if self.item_count is not None:
            p["item_count"] = self.item_count
        return p

    def children(self) -> list[WidgetChild]:
        # Schema API has no function transport, so builder mode
        # materializes its items eagerly. The JS compiler keeps the
        # builder lazy (see the compiler pipeline).
        if self.item_builder is not None and isinstance(self.item_count, int):
            return [self.item_builder(i) for i in range(self.item_count)]
        return self._children
